package com.fishinvcounter;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(FishInvCounterConfig.GROUP)
public interface FishInvCounterConfig extends Config
{
	String GROUP = "fishinvcounter";

	@ConfigSection(name = "Goals", description = "Goal and counting settings", position = 0)
	String goalsSection = "goals";

	@ConfigSection(name = "Overlay", description = "How the overlay looks", position = 1)
	String overlaySection = "overlay";

	@ConfigSection(name = "Colors", description = "Overlay colors", position = 3, closedByDefault = true)
	String colorsSection = "colors";

	enum GoalType
	{
		INVENTORY_COUNT,
		FISHING_LEVEL;

		@Override
		public String toString()
		{
			return this == INVENTORY_COUNT ? "Inventory count" : "Fishing level";
		}
	}

	// ---- Goals ----

	@ConfigItem(keyName = "goalType", name = "Goal type", position = 0, section = goalsSection,
		description = "Aim for a number of inventories, or a Fishing level")
	default GoalType goalType()
	{
		return GoalType.INVENTORY_COUNT;
	}

	@ConfigItem(keyName = "goal", name = "Inventory goal", position = 1, section = goalsSection,
		description = "How many full inventories of fish you want to reach")
	default int goal()
	{
		return 10;
	}

	@ConfigItem(keyName = "targetLevel", name = "Level goal", position = 2, section = goalsSection,
		description = "Fishing level to aim for when Goal type is Fishing level")
	default int targetLevel()
	{
		return 80;
	}

	@ConfigItem(keyName = "count", name = "Current count", position = 3, section = goalsSection,
		description = "Full fish inventories so far. Set to 0 to reset.")
	default int count()
	{
		return 0;
	}

	@ConfigItem(keyName = "dailyGoal", name = "Daily goal", position = 4, section = goalsSection,
		description = "Inventories per day for your streak. 0 = off.")
	default int dailyGoal()
	{
		return 0;
	}

	@ConfigItem(keyName = "fishList", name = "Only count these fish", position = 5, section = goalsSection,
		description = "Comma separated fish names, e.g. Raw lobster, Raw swordfish. Empty = all fish.")
	default String fishList()
	{
		return "";
	}

	@ConfigItem(keyName = "chatMessages", name = "Chat messages", position = 6, section = goalsSection,
		description = "Post the count in chat each time it goes up")
	default boolean chatMessages()
	{
		return true;
	}

	@ConfigItem(keyName = "notifyOnGoal", name = "Notify on goal", position = 7, section = goalsSection,
		description = "Send a notification when you hit a goal")
	default boolean notifyOnGoal()
	{
		return true;
	}

	@ConfigItem(keyName = "soundOnGoal", name = "Sound on goal", position = 8, section = goalsSection,
		description = "Play a sound when you hit a goal")
	default boolean soundOnGoal()
	{
		return true;
	}

	// ---- Overlay ----

	@ConfigItem(keyName = "showOverlay", name = "Show overlay", position = 1, section = overlaySection,
		description = "Show the counter box on screen")
	default boolean showOverlay()
	{
		return true;
	}

	@ConfigItem(keyName = "onlyWhileFishing", name = "Only while fishing", position = 2, section = overlaySection,
		description = "Hide the overlay if you haven't caught a fish in 5 minutes")
	default boolean onlyWhileFishing()
	{
		return false;
	}

	@ConfigItem(keyName = "compactMode", name = "Compact mode", position = 3, section = overlaySection,
		description = "Show one line with the count only")
	default boolean compactMode()
	{
		return false;
	}

	@ConfigItem(keyName = "hideTitle", name = "Hide title", position = 4, section = overlaySection,
		description = "Hide the 'Fish Inventories' title")
	default boolean hideTitle()
	{
		return false;
	}

	@ConfigItem(keyName = "showCount", name = "Show count", position = 5, section = overlaySection,
		description = "Show the inventory count line")
	default boolean showCount()
	{
		return true;
	}

	@ConfigItem(keyName = "showEta", name = "Show time left", position = 6, section = overlaySection,
		description = "Show time left to your goal")
	default boolean showEta()
	{
		return true;
	}

	@ConfigItem(keyName = "showInvPerHour", name = "Show inventories/hr", position = 7, section = overlaySection,
		description = "Show inventories per hour")
	default boolean showInvPerHour()
	{
		return false;
	}

	@ConfigItem(keyName = "showXpGained", name = "Show XP gained", position = 8, section = overlaySection,
		description = "Show Fishing XP gained this session")
	default boolean showXpGained()
	{
		return false;
	}

	@ConfigItem(keyName = "showXpPerInv", name = "Show XP/inventory", position = 9, section = overlaySection,
		description = "Show average XP per full inventory")
	default boolean showXpPerInv()
	{
		return false;
	}

	@ConfigItem(keyName = "showXpPerHour", name = "Show XP/hr", position = 10, section = overlaySection,
		description = "Show Fishing XP per hour")
	default boolean showXpPerHour()
	{
		return false;
	}

	// ---- Colors ----

	@ConfigItem(keyName = "titleColor", name = "Title", position = 1, section = colorsSection,
		description = "Title text color")
	default Color titleColor()
	{
		return Color.WHITE;
	}

	@ConfigItem(keyName = "textColor", name = "Text", position = 2, section = colorsSection,
		description = "Count and info text color")
	default Color textColor()
	{
		return Color.WHITE;
	}

	@Alpha
	@ConfigItem(keyName = "barColor", name = "Bar", position = 3, section = colorsSection,
		description = "Progress bar color")
	default Color barColor()
	{
		return new Color(0, 110, 200);
	}

	@Alpha
	@ConfigItem(keyName = "barDoneColor", name = "Bar (goal reached)", position = 4, section = colorsSection,
		description = "Progress bar color once the goal is reached")
	default Color barDoneColor()
	{
		return new Color(0, 160, 0);
	}

	@Alpha
	@ConfigItem(keyName = "barBackgroundColor", name = "Bar background", position = 5, section = colorsSection,
		description = "Empty part of the progress bar")
	default Color barBackgroundColor()
	{
		return new Color(60, 60, 60, 200);
	}
}

package com.fishinvcounter;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Experience;
import net.runelite.api.MenuAction;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class FishInvCounterOverlay extends OverlayPanel
{
	private final FishInvCounterPlugin plugin;
	private final FishInvCounterConfig config;

	@Inject
	FishInvCounterOverlay(FishInvCounterPlugin plugin, FishInvCounterConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, "Undo last", "Fish Inventories", e -> plugin.undoLast());
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay() || (config.onlyWhileFishing() && !plugin.isRecentlyFishing()))
		{
			return null;
		}

		boolean levelMode = config.goalType() == FishInvCounterConfig.GoalType.FISHING_LEVEL;
		return levelMode ? renderLevelGoal(graphics) : renderCountGoal(graphics);
	}

	private Dimension renderCountGoal(Graphics2D graphics)
	{
		int count = config.count();
		int goal = Math.max(1, config.goal());
		boolean done = count >= goal;

		if (config.compactMode())
		{
			panelComponent.getChildren().add(line("Fish:", count + " / " + goal));
			return super.render(graphics);
		}

		addTitle();
		if (config.showCount())
		{
			panelComponent.getChildren().add(line("Count:", count + " / " + goal));
		}

		double perHour = plugin.shownInventoriesPerHour();
		if (config.showEta() && !done && perHour > 0)
		{
			panelComponent.getChildren().add(line("Time left:", formatHours((goal - count) / perHour)));
		}

		addExtraLines();
		addBar(0, goal, Math.min(count, goal), done);
		return super.render(graphics);
	}

	private Dimension renderLevelGoal(Graphics2D graphics)
	{
		int level = Math.max(2, Math.min(config.targetLevel(), Experience.MAX_REAL_LEVEL));
		int xp = plugin.currentXp();
		String label = "Lvl " + level + ":";

		if (xp < 0)
		{
			// XP isn't known until the first XP update after logging in / enabling the plugin
			panelComponent.getChildren().add(line(label, "catch a fish"));
			return super.render(graphics);
		}

		int targetXp = Experience.getXpForLevel(level);
		int xpLeft = targetXp - xp;
		boolean done = xpLeft <= 0;
		int xpPerInv = plugin.xpPerInventory();
		int invsLeft = xpPerInv > 0 ? (int) Math.ceil(xpLeft / (double) xpPerInv) : -1;

		String remaining;
		if (done)
		{
			remaining = "Done!";
		}
		else if (invsLeft > 0)
		{
			remaining = invsLeft + (invsLeft == 1 ? " inv" : " invs");
		}
		else
		{
			remaining = String.format("%,d xp", xpLeft);
		}

		if (config.compactMode())
		{
			panelComponent.getChildren().add(line(label, remaining));
			return super.render(graphics);
		}

		addTitle();
		panelComponent.getChildren().add(line(label, remaining));
		if (config.showCount())
		{
			panelComponent.getChildren().add(line("Count:", String.valueOf(config.count())));
		}

		double perHour = plugin.shownInventoriesPerHour();
		if (config.showEta() && !done && invsLeft > 0 && perHour > 0)
		{
			panelComponent.getChildren().add(line("Time left:", formatHours(invsLeft / perHour)));
		}

		addExtraLines();
		int startXp = Math.min(plugin.levelGoalStartXp(level), targetXp - 1);
		addBar(startXp, targetXp, Math.min(xp, targetXp), done);
		return super.render(graphics);
	}

	private void addTitle()
	{
		if (!config.hideTitle())
		{
			panelComponent.getChildren().add(TitleComponent.builder()
				.text("Fish Inventories")
				.color(config.titleColor())
				.build());
		}
	}

	/** Optional lines shared by both goal types. */
	private void addExtraLines()
	{
		double perHour = plugin.shownInventoriesPerHour();
		if (config.showInvPerHour() && perHour > 0)
		{
			panelComponent.getChildren().add(line("Invs/hr:", String.format("%.1f", perHour)));
		}

		if (plugin.currentXp() >= 0)
		{
			if (config.showXpGained())
			{
				panelComponent.getChildren().add(line("XP gained:", String.format("%,d", plugin.sessionXp())));
			}
			if (config.showXpPerInv() && plugin.xpPerInventory() > 0)
			{
				panelComponent.getChildren().add(line("XP/inv:", String.format("%,d", plugin.xpPerInventory())));
			}
			double xpHr = plugin.shownXpPerHour();
			if (config.showXpPerHour() && xpHr > 0)
			{
				panelComponent.getChildren().add(line("XP/hr:", String.format("%,d", Math.round(xpHr))));
			}
		}

		int dailyGoal = config.dailyGoal();
		if (dailyGoal > 0)
		{
			panelComponent.getChildren().add(line("Today:", plugin.dailyCount() + " / " + dailyGoal));
			int streak = plugin.streak();
			panelComponent.getChildren().add(line("Streak:", streak + (streak == 1 ? " day" : " days")));
		}
	}

	private void addBar(int min, int max, int value, boolean done)
	{
		ProgressBarComponent bar = new ProgressBarComponent();
		bar.setMinimum(min);
		bar.setMaximum(max);
		bar.setValue(value);
		bar.setForegroundColor(done ? config.barDoneColor() : config.barColor());
		bar.setBackgroundColor(config.barBackgroundColor());
		panelComponent.getChildren().add(bar);
	}

	private LineComponent line(String left, String right)
	{
		return LineComponent.builder()
			.left(left)
			.leftColor(config.textColor())
			.right(right)
			.rightColor(config.textColor())
			.build();
	}

	static String formatHours(double hours)
	{
		long minutes = Math.round(hours * 60);
		return minutes >= 60 ? (minutes / 60) + "h " + (minutes % 60) + "m" : minutes + "m";
	}
}

package com.fishinvcounter;

import com.google.common.collect.ImmutableSet;
import com.google.inject.Provides;
import java.time.Duration;
import java.time.Instant;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.task.Schedule;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@PluginDescriptor(
	name = "Fish Inventory Counter",
	description = "Counts how many inventories of fish you've filled, with a custom goal",
	tags = {"fishing", "fish", "counter", "goal"}
)
public class FishInvCounterPlugin extends Plugin
{
	private static final int INVENTORY_ID = 93;
	private static final int INVENTORY_SIZE = 28;
	private static final int GOAL_SOUND_ID = 3925; // GE offer "ding"
	private static final Duration FISHING_TIMEOUT = Duration.ofMinutes(5);

	private static final Set<String> FISH = ImmutableSet.of(
		"raw shrimps", "raw anchovies", "raw sardine", "raw herring", "raw mackerel",
		"raw trout", "raw cod", "raw pike", "raw salmon", "raw tuna", "raw rainbow fish",
		"raw lobster", "raw bass", "raw swordfish", "raw monkfish", "raw shark",
		"raw sea turtle", "raw manta ray", "raw anglerfish", "raw dark crab",
		"raw karambwan", "raw cave eel", "raw slimy eel", "raw lava eel",
		"leaping trout", "leaping salmon", "leaping sturgeon",
		"infernal eel", "sacred eel", "raw guppy", "raw cavefish", "raw tetra", "raw catfish"
	);

	@Inject private Client client;
	@Inject private FishInvCounterConfig config;
	@Inject private ConfigManager configManager;
	@Inject private ItemManager itemManager;
	@Inject private Notifier notifier;
	@Inject private OverlayManager overlayManager;
	@Inject private FishInvCounterOverlay overlay;

	// null = no baseline yet (just logged in / hopped), so we don't count the starting inventory
	private Integer lastFishCount;
	private boolean lastFull;

	private Instant lastCatch;
	private Instant sessionStart;
	private int sessionInventories;

	// Fishing XP: -1 = not known yet (StatChanged fires for every skill on login)
	private int currentXp = -1;
	private int sessionStartXp = -1;
	private int sessionXpAtLastCount;

	// Rates refreshed every few seconds so the overlay numbers don't flicker
	private volatile double invPerHourShown = -1;
	private volatile double xpPerHourShown = -1;

	@Provides
	FishInvCounterConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(FishInvCounterConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		lastFishCount = null;
		lastCatch = null;
		resetSession();
	}

	private void resetSession()
	{
		sessionStart = null;
		sessionInventories = 0;
		currentXp = -1;
		sessionStartXp = -1;
		sessionXpAtLastCount = 0;
		invPerHourShown = -1;
		xpPerHourShown = -1;
	}

	@Schedule(period = 3, unit = ChronoUnit.SECONDS)
	public void refreshRates()
	{
		invPerHourShown = inventoriesPerHour();
		xpPerHourShown = xpPerHour();
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			lastFishCount = null;
		}
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			resetSession();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.FISHING)
		{
			return;
		}
		int previousXp = currentXp;
		currentXp = event.getXp();
		if (sessionStartXp < 0)
		{
			sessionStartXp = currentXp;
		}

		if (config.goalType() == FishInvCounterConfig.GoalType.FISHING_LEVEL && previousXp >= 0)
		{
			int level = Math.min(config.targetLevel(), Experience.MAX_REAL_LEVEL);
			int targetXp = Experience.getXpForLevel(Math.max(level, 2));
			if (previousXp < targetXp && currentXp >= targetXp)
			{
				goalReached("Fishing level goal reached! Level " + level + "!");
			}
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != INVENTORY_ID)
		{
			return;
		}

		ItemContainer inv = event.getItemContainer();
		Set<String> fishNames = fishNames();
		int used = 0;
		int fish = 0;
		for (Item item : inv.getItems())
		{
			if (item.getId() == -1 || item.getQuantity() <= 0)
			{
				continue;
			}
			used++;
			if (isFish(item.getId(), fishNames))
			{
				fish++;
			}
		}
		boolean full = used >= INVENTORY_SIZE;

		if (lastFishCount != null && fish > lastFishCount)
		{
			lastCatch = Instant.now();
			if (sessionStart == null)
			{
				sessionStart = lastCatch;
			}
		}

		// Count when the inventory just became full because you caught a fish
		if (lastFishCount != null && !lastFull && full && fish > lastFishCount)
		{
			addOne();
		}

		lastFishCount = fish;
		lastFull = full;
	}

	private Set<String> fishNames()
	{
		String list = config.fishList();
		if (list == null || list.trim().isEmpty())
		{
			return FISH;
		}
		ImmutableSet.Builder<String> names = ImmutableSet.builder();
		for (String name : Text.fromCSV(list))
		{
			names.add(name.toLowerCase());
		}
		return names.build();
	}

	private boolean isFish(int itemId, Set<String> fishNames)
	{
		String name = itemManager.getItemComposition(itemId).getName();
		return name != null && fishNames.contains(name.toLowerCase());
	}

	private void addOne()
	{
		int count = config.count() + 1;
		int goal = config.goal();
		setInt("count", count);
		sessionInventories++;

		if (sessionStartXp >= 0)
		{
			sessionXpAtLastCount = currentXp - sessionStartXp;
			// Saved so the "inventories to level" estimate works right away next session
			setInt("xpPerInventory", sessionXpAtLastCount / sessionInventories);
		}

		String today = LocalDate.now().toString();
		int daily = dailyCount() + 1;
		setInt("dailyCount", daily);
		configManager.setConfiguration(FishInvCounterConfig.GROUP, "dailyDate", today);

		if (config.chatMessages())
		{
			boolean countGoal = config.goalType() == FishInvCounterConfig.GoalType.INVENTORY_COUNT;
			chat("Fish inventories: " + count + (countGoal ? " / " + goal : ""));
		}

		if (config.goalType() == FishInvCounterConfig.GoalType.INVENTORY_COUNT && count == goal)
		{
			goalReached("Fishing goal reached! " + goal + " inventories!");
		}

		int dailyGoal = config.dailyGoal();
		if (dailyGoal > 0 && daily == dailyGoal)
		{
			String yesterday = LocalDate.now().minusDays(1).toString();
			int streak = yesterday.equals(getString("streakDate")) ? getInt("streak") + 1 : 1;
			setInt("streak", streak);
			configManager.setConfiguration(FishInvCounterConfig.GROUP, "streakDate", today);
			goalReached("Daily fishing goal done! Streak: " + streak + (streak == 1 ? " day" : " days"));
		}
	}

	void undoLast()
	{
		int count = config.count();
		if (count <= 0)
		{
			return;
		}
		setInt("count", count - 1);
		if (dailyCount() > 0)
		{
			setInt("dailyCount", dailyCount() - 1);
		}
		if (sessionInventories > 0)
		{
			sessionInventories--;
		}
		chat("Undid last fish inventory. Now: " + (count - 1) + " / " + config.goal());
	}

	private void goalReached(String message)
	{
		chat("<col=00ff00>" + message + "</col>");
		if (config.notifyOnGoal())
		{
			notifier.notify(message);
		}
		if (config.soundOnGoal())
		{
			client.playSoundEffect(GOAL_SOUND_ID);
		}
	}

	private void chat(String message)
	{
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
	}

	// ---- Values the overlay reads ----

	int dailyCount()
	{
		// Resets automatically when the saved date isn't today
		return LocalDate.now().toString().equals(getString("dailyDate")) ? getInt("dailyCount") : 0;
	}

	int streak()
	{
		String date = getString("streakDate");
		String today = LocalDate.now().toString();
		String yesterday = LocalDate.now().minusDays(1).toString();
		// Streak is only alive if the daily goal was hit today or yesterday
		return today.equals(date) || yesterday.equals(date) ? getInt("streak") : 0;
	}

	boolean isRecentlyFishing()
	{
		return lastCatch != null && Duration.between(lastCatch, Instant.now()).compareTo(FISHING_TIMEOUT) < 0;
	}

	/** XP when this level goal was first seen, so the bar starts empty instead of nearly full. */
	int levelGoalStartXp(int level)
	{
		String key = "levelStartXp" + level;
		int saved = getInt(key);
		if (saved == 0 && currentXp > 0)
		{
			setInt(key, currentXp);
			return currentXp;
		}
		return saved;
	}

	double shownInventoriesPerHour()
	{
		return invPerHourShown;
	}

	double shownXpPerHour()
	{
		return xpPerHourShown;
	}

	/** Inventories per hour this session, or -1 if not enough data yet. */
	private double inventoriesPerHour()
	{
		if (sessionStart == null || sessionInventories == 0)
		{
			return -1;
		}
		// shortcut: counts AFK/bank time since first catch, so the rate drops if you stop fishing; fine for a rough ETA
		double hours = Duration.between(sessionStart, Instant.now()).toMillis() / 3_600_000.0;
		return hours <= 0 ? -1 : sessionInventories / hours;
	}

	int currentXp()
	{
		return currentXp;
	}

	int sessionXp()
	{
		return sessionStartXp < 0 ? 0 : currentXp - sessionStartXp;
	}

	/** Average XP per full inventory: this session if available, otherwise the last saved value. 0 = unknown. */
	int xpPerInventory()
	{
		// shortcut: if you log in with a half-full inventory, the first one undercounts; evens out over a session
		if (sessionInventories > 0 && sessionXpAtLastCount > 0)
		{
			return sessionXpAtLastCount / sessionInventories;
		}
		return getInt("xpPerInventory");
	}

	/** Fishing XP per hour this session, or -1 if not enough data yet. */
	private double xpPerHour()
	{
		if (sessionStart == null || sessionXp() <= 0)
		{
			return -1;
		}
		double hours = Duration.between(sessionStart, Instant.now()).toMillis() / 3_600_000.0;
		return hours <= 0 ? -1 : sessionXp() / hours;
	}

	// ---- Hidden saved values ----

	private int getInt(String key)
	{
		Integer value = configManager.getConfiguration(FishInvCounterConfig.GROUP, key, Integer.class);
		return value == null ? 0 : value;
	}

	private String getString(String key)
	{
		return configManager.getConfiguration(FishInvCounterConfig.GROUP, key);
	}

	private void setInt(String key, int value)
	{
		configManager.setConfiguration(FishInvCounterConfig.GROUP, key, value);
	}
}

